import 'package:mad_flutter_practicum/app/app.dart';
import 'package:mad_flutter_practicum/domain/domain.dart';

import 'widgets/widgets.dart';

class NewsListPage extends StatefulWidget {
  const NewsListPage({super.key});

  @override
  State<NewsListPage> createState() => NewsListPageState();
}

class NewsListPageState extends State<NewsListPage> with SingleTickerProviderStateMixin {
  static final _tween = Tween<double>(begin: 0.25, end: 1);

  late Future<List<NewsModel>> _newsListFuture;

  late final AnimationController _scaleController;
  late final Animation<double> _scaleAnimation;

  @override
  void initState() {
    super.initState();
    _initAnimation();
    _newsListFuture = _loadNews();
  }

  @override
  void dispose() {
    _scaleController.dispose();
    super.dispose();
  }

  void _initAnimation() {
    _scaleController = AnimationController(
      vsync: this,
      duration: Duration(milliseconds: 200),
    );
    _scaleAnimation = _tween.animate(_scaleController);
  }

  Future<List<NewsModel>> _loadNews() async {
    final newsRepository = context.read<NewsRepository>();

    return newsRepository.loadNewsFeed(const NewsFeedFilter(forceRefresh: true)).then((List<NewsModel> value) {
      if (mounted) {
        setState(() {}); // триггерим перестроение после получения данных
      }

      _scaleController.forward(); // запускаем анимацию

      return value;
    });
  }

  void refresh() {
    setState(() {
      _newsListFuture = _loadNews();
    });
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text(context.loc.news)),
      body: FutureBuilder<List<NewsModel>>(
        future: _newsListFuture,
        builder: (BuildContext context, AsyncSnapshot<List<NewsModel>> snapshot) {
          final List<NewsModel>? data = snapshot.data;
          if (data == null) return const SizedBox.shrink();

          return ScaleTransition(
            scale: _scaleAnimation,
            child: ListView.builder(
              itemCount: data.length,
              itemBuilder: (BuildContext context, int index) {
                final NewsModel news = data[index];

                return Padding(
                  key: ValueKey(news.link),
                  padding: index == 0 ? EdgeInsets.zero : const EdgeInsets.only(top: 16),
                  child: NewsCard(model: news),
                );
              },
              padding: const EdgeInsets.fromLTRB(22, 16, 22, 40),
            ),
          );
        },
      ),
    );
  }
}

message.reasoning_content:
Теперь нужно обновить HomePage:
1. Добавить GlobalKey для CurrencyListPageState и NewsListPageState
2. Создать метод _refreshAll() который вызывает refresh() на активной странице
3. Добавить AppBar с кнопкой refresh

Но есть проблема - в текущем коде страницы создаются один раз как статичные виджеты в списке _pages, а затем индексируются по индексу. Если мы используем GlobalKey, нам нужно убедиться что State-объекты доступны.

Подход: вместо создания страниц как константных виджетов, будем создавать их при первом рендере и сохранять в state.

Давайте подумаем о подходе:
1. Вариант A: Сделать страницы с GlobalKey, но они создадутся один раз и будут храниться в _pages списке. Проблема - если мы переключим вкладку и вернёмся, то State всё ещё будет жив, так что GlobalKey должен работать.

Но проблема в том, что сейчас страницы создаются как константные виджеты (const) внутри списка _pages. Если мы хотим использовать GlobalKey, нам нужно создать экземпляры страниц, а не const-версии.

Лучший подход:
- Убрать страницы из статического списка _pages
- Создать их в initState или как lazy-loaded state переменные
- Использовать GlobalKey для доступа к State каждой страницы

Или ещё проще - просто использовать ключи (Keys) и setState при refresh. Но без GlobalKey мы не сможем получить currentState.

Давайте посмотрим на текущий код HomePage более внимательно:

```dart
static const List<Widget> _pages = <Widget>[
  CurrencyListPage(),
  NewsListPage(),
  ProfilePage(),
];
```

Проблема здесь в том, что эти страницы создаются один раз при старте приложения. Если мы хотим чтобы refresh работал на активной странице, нам нужно:
1. Либо сделать GlobalKey для каждой страницы и хранить экземпляры в state
2. Либо использовать какой-то механизм коммуникации (ValueNotifier, StreamController, Provider)

Вариант с GlobalKey проще всего реализовать. Давайте переделаем HomePage так:

```dart
class _HomePageState extends State<HomePage> {
  int _selectedIndex = 0;
  final GlobalKey<CurrencyListPageState> _currencyPageKey = GlobalKey();
  final GlobalKey<NewsListPageState> _newsPageKey = GlobalKey();

  late final List<Widget> _pages;

  @override
  void initState() {
    super.initState();
    _pages = [
      CurrencyListPage(key: _currencyPageKey),
      NewsListPage(key: _newsPageKey),
      ProfilePage(),
    ];
  }

  Future<void> _refreshAll() async {
    switch (_selectedIndex) {
      case 0:
        _currencyPageKey.currentState?.refresh();
        break;
      case 1:
        _newsPageKey.currentState?.refresh();
        break;
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: Text(context.loc.currencyRate), // Нужно менять в зависимости от страницы? Или всегда один заголовок
        actions: [
          IconButton(
            icon: Icon(Icons.refresh),
            onPressed: _refreshAll,
          ),
        ],
      ),
      body: _pages[_selectedIndex],
      bottomNavigationBar: ...,
    );
  }
}
```

Но есть проблема - AppBar показывает currencyRate независимо от выбранной вкладки. Это может быть некорректно с точки зрения UX. Давайте посмотрим на локализации и решим, что делать с заголовком.

На самом деле, можно сделать так:
- Если выбрана CurrencyListPage -> показываем currencyRate
- Если выбрана NewsListPage -> показываем news  
- Если ProfilePage -> показываем profile (или пусто)

Или проще - всегда показывать refresh кнопку, а заголовок AppBar менять в зависимости от выбранной страницы.

Давайте реализуем это правильно:

```dart
appBar: _selectedIndex == 0 
  ? AppBar(title: Text(context.loc.currencyRate), actions: [...])
  : _selectedIndex == 1 
    ? AppBar(title: Text(context.loc.news), actions: [...])
    : null, // для ProfilePage не показываем AppBar или показываем без refresh кнопки
```

Или ещё лучше - всегда показывать AppBar с refresh кнопкой, но менять заголовок. Но для ProfilePage это может быть избыточно. Давайте посмотрим на оригинальный код - там нет AppBar в HomePage, он есть только внутри каждой страницы (CurrencyListPage и NewsListPage).

Если мы добавим AppBar в HomePage, то на CurrencyListPage будет двойной AppBar (один от HomePage, один от CurrencyListPage). Это плохо.

Нужно другой подход:
1. Убрать AppBar из CurrencyListPage и NewsListPage, перенеся его в HomePage
2. Или использовать механизм коммуникации вместо GlobalKey

Второй вариант более чистый с точки зрения Clean Architecture, но сложнее в реализации. Первый проще, но требует рефакторинга двух файлов.

Давайте посмотрим на тесты - возможно, они проверяют наличие AppBar внутри страниц:

